		if diff.Direction.X != nil {
			result.Direction.X = *diff.Direction.X
		}
		if diff.Direction.Y != nil {
			result.Direction.Y = *diff.Direction.Y
		}
		if diff.Direction.Z != nil {
			result.Direction.Z = *diff.Direction.Z
		}
	}
	return result
}
```

